import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  // Validate issueDate is a valid date in YYYY-MM-DD format
  if (!/^\d{4}-\d{2}-\d{2}$/.test(issueDate)) return fail('DATE_INVALID');
  const date = new Date(issueDate + 'T00:00:00Z');
  if (isNaN(date.getTime())) return fail('DATE_INVALID');
  // Verify the date round-trips correctly (e.g., 2026-02-30 would be normalized to 2026-03-02)
  const [year, month, day] = issueDate.split('-').map(Number);
  if (date.getUTCFullYear() !== year || date.getUTCMonth() + 1 !== month || date.getUTCDate() !== day) {
    return fail('DATE_INVALID');
  }

  // Validate lines array is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Expand lines with product data
  const expandedLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Get product from catalogue
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    expandedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: expandedLines,
  });
}

/**
 * Calculate the total for a single line (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} Total in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate subtotal and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }} invoice
 * @returns {{ subtotal: number, total: number }} Amounts in cents
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  return {
    subtotal,
    total: subtotal,
  };
}

/**
 * Add or increase a line on a draft invoice.
 * @param {Object} invoice
 * @param {{ sku: string, qty: number }} input
 * @returns {{ ok: true, value: Object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty }) {
  // Check draft status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty is a positive integer
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Get product from catalogue
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Find existing line with this SKU
  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  // Create new lines array with the change
  const newLines = invoice.lines.map((line) => ({ ...line }));

  if (existingLineIndex >= 0) {
    // Increase quantity on existing line
    newLines[existingLineIndex].qty += qty;
  } else {
    // Add new line at the end
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {Object} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: Object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check draft status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find the line to remove
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  // Check if this is the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new lines array without this line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice with a number and status change.
 * @param {Object} invoice
 * @param {string[]} existingNumbers Array of invoice numbers already used
 * @returns {{ ok: true, value: Object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check draft status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Generate next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

